    "start.title": "Desde dónde trabajas",
    "start.sub": "La ciudad donde vives o donde estás ahora, y tu número de teléfono. Las nuevas sesiones se crean en esa ciudad, y un viaje a otra la app lo deduce sola. Ambas respuestas se cambian en los ajustes.",
    "start.cityPh": "Ciudad",
    "start.telPh": "Teléfono",
    "start.note": "Tu número es tu dirección hacia fuera: por él un organizador enlaza tus sesiones con su plan. Puedes dejarlo vacío y escribirlo después.",
    "tour.skip": "Omitir",
