    "tour.row": "Introducción",
    "tour.rowV": "Ver",
    "tour.hi.t": "Light Plan",
    "tour.hi.d": "Luz, clima y sesiones en un solo lugar. Te lo muestro en un minuto y sobre la pantalla real. Puedes salir en cualquier paso.",
    "tour.dome.t": "La cúpula de luz",
    "tour.dome.d": "El arco es el camino del sol de la salida a la puesta, el disco es dónde está ahora. La marca hacia abajo muestra su altura y la longitud de la sombra.",
    "tour.time.t": "El tiempo en la mano",
    "tour.time.d": "El deslizador mueve el tiempo: la cúpula, la telemetría y el clima se recalculan para ese minuto. Es el mismo deslizador en «Luz» y en «Mapa».",
    "tour.sky.t": "Sol o luna",
    "tour.sky.d": "El interruptor cambia el astro en la cúpula. La luna tiene el mismo arco, su propia fase y su propia salida y puesta.",
    "tour.tele.t": "El panel de instrumentos",
    "tour.tele.d": "Condiciones, atardecer, hora dorada, luz, sombras, cielo, viento. Las filas cambian junto con la hora del deslizador.",
    "tour.place.t": "Dónde fotografías",
    "tour.place.d": "La luz se calcula donde fotografías. El lugar se cambia tocando el encabezado — por ubicación, por búsqueda o por coordenadas.",
    "tour.map.t": "La brújula de la luz",
    "tour.map.d": "En el mapa se ve de dónde llega el sol y hacia dónde cae la sombra. Mueves el tiempo y el rayo lo sigue.",
    "tour.cal.t": "Un calendario de sesiones",
    "tour.cal.d": "Mes, semana o un solo día. El género va en la celda con palabras, no con un punto.",
    "tour.stats.t": "El año se cuenta solo",
    "tour.stats.d": "El calendario resume el año: cuánto se fotografió y qué viene, por género, con plazos de entrega y dinero. No hay que cargar nada aparte.",
    "tour.add.t": "Tu primera sesión",
    "tour.add.d": "El botón crea un registro: fecha, género, lugar, hora de inicio. De ahí en adelante el calendario y la luz trabajan juntos.",
    "tour.bin.t": "La papelera",
    "tour.bin.d": "Una sesión eliminada no desaparece: queda en la papelera y vuelve a su lugar con un botón. La fila aparece aquí en cuanto la papelera tiene algo.",
    "tour.mode.t": "Simple y Astro",
    "tour.mode.d": "«Simple» deja en las pantallas solo lo que hace falta para fotografiar. «Astro» agrega azimuts, altura del sol, longitud de la sombra, crepúsculo y la cinta del día bajo el deslizador.",
    "tour.cloud.t": "Una copia en tu nube",
    "tour.cloud.d": "Yandex Disk, Google o Dropbox: ahí van la copia de los datos y las referencias de las sesiones. A nuestro servidor no va nada.",
    "tour.end.t": "Eso es todo",
    "tour.end.d": "La introducción vive en los ajustes y se repite cuando quieras — entera o desde el paso que necesites.",
    "set.curNote": "Moneda por defecto para una sesión nueva: {sample}. En cada sesión se puede cambiar — en el bloque «Pago» del formulario. No depende del idioma: al cambiar el idioma la moneda queda igual.",
    "set.legal": "Información legal",
    "set.privacy": "Las sesiones, los lugares y los ajustes se guardan en tu dispositivo. A nuestro servidor no va nada — no existe.",
